"use strict";$(document).ready(function(){$("#calendar").fullCalendar({theme:!0,header:{left:"prev",center:"title",right:"next"},editable:!1,events:function(n,t,i,r){$.ajax({url:_global.root+"Calendar/GetWorkingSchedule",dataType:"json",method:"GET",data:{date:$("#calendar").fullCalendar("getDate").format("MM/DD/YYYY"),employeeId:_global.employeeId},success:function(n){var t=[];$(n).each(function(n,i){var u=formatDate(new Date,"dd/MM/yyyy"),r=i.Title;u===formatDate(i.WorkDate,"dd/MM/yyyy")&&(r=r+" today");t.push({title:i.Title,start:i.WorkDate,className:r})});r(t)}})}})});